-- Mileage rates are set in tenths of a cent, as the IRS sets them (72.5 cents a
-- mile for 2026), so business and expense rates are kept in thousandths of the
-- currency unit. Per diem rates copied onto expenses move to the same unit.
ALTER TABLE c_business RENAME COLUMN mileage_rate_minor TO mileage_rate_thousandths;
UPDATE c_business SET mileage_rate_thousandths = mileage_rate_thousandths * 10;
ALTER TABLE c_items RENAME COLUMN rate_minor TO rate_thousandths;
UPDATE c_items SET rate_thousandths = rate_thousandths * 10;

-- US-first defaults (LOCALE-001). The mileage rate becomes an effective-dated
-- table (seeded with the IRS standard business rates when a USD business is
-- set up) and each mileage expense takes the rate in force on its trip date; an
-- existing single rate carries over as the rate for every date. Receipts carry
-- sales tax as their own amount, copied with the business's sales tax account
-- and tax code onto the expense; a category can always need a receipt (lodging).
CREATE TABLE c_mileage_rates (
  effective_from TEXT PRIMARY KEY CHECK (effective_from GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  rate_thousandths INTEGER NOT NULL CHECK (rate_thousandths > 0)
);
INSERT INTO c_mileage_rates(effective_from, rate_thousandths) SELECT '2000-01-01', mileage_rate_thousandths FROM c_business WHERE mileage_rate_thousandths > 0;
ALTER TABLE c_business DROP COLUMN mileage_rate_thousandths;
ALTER TABLE c_business ADD COLUMN sales_tax_account TEXT NOT NULL DEFAULT '';
ALTER TABLE c_business ADD COLUMN sales_tax_code TEXT NOT NULL DEFAULT '';
ALTER TABLE c_categories ADD COLUMN receipt_always INTEGER NOT NULL DEFAULT 0 CHECK (receipt_always IN (0, 1));
ALTER TABLE c_items ADD COLUMN sales_tax_minor INTEGER NOT NULL DEFAULT 0 CHECK (sales_tax_minor >= 0);
ALTER TABLE c_items ADD COLUMN sales_tax_account TEXT NOT NULL DEFAULT '';
ALTER TABLE c_items ADD COLUMN sales_tax_code TEXT NOT NULL DEFAULT '';

-- Auditors read every record and change nothing (REPORT-003). History search
-- and audit packs read history lines by time.
ALTER TABLE c_members ADD COLUMN is_auditor INTEGER NOT NULL DEFAULT 0 CHECK (is_auditor IN (0, 1));
CREATE INDEX c_events_at ON c_events(at);

-- Itemization, attendees and required fields (CLAIM-007). Each part of a split
-- names what it is (room, tax, in-room dining); categories may limit spend per
-- person and name custom fields every expense in them must fill.
ALTER TABLE c_allocations ADD COLUMN description TEXT NOT NULL DEFAULT '';
ALTER TABLE c_categories ADD COLUMN per_person_limit_minor INTEGER CHECK (per_person_limit_minor IS NULL OR per_person_limit_minor >= 0);
ALTER TABLE c_categories ADD COLUMN required_fields TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(required_fields));
ALTER TABLE c_items ADD COLUMN attendees TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(attendees));
ALTER TABLE c_items ADD COLUMN fields TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(fields));

-- Hold one expense, approve the rest (APPROVE-005). The held expenses move to a
-- new claim that stays with the employee and names the claim it came from, the
-- approver who held it, when, and why.
ALTER TABLE c_claims ADD COLUMN held_from TEXT;
ALTER TABLE c_claims ADD COLUMN held_by TEXT;
ALTER TABLE c_claims ADD COLUMN held_at TEXT;
ALTER TABLE c_claims ADD COLUMN hold_reason TEXT;

-- Rule-based auto-approval (APPROVE-004). Every change the owner makes to the
-- rule is a new numbered version; a claim the rule approves records "rule vN".
CREATE TABLE c_approval_rules (
  version INTEGER PRIMARY KEY CHECK (version >= 1),
  enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),
  limit_minor INTEGER CHECK (limit_minor IS NULL OR limit_minor > 0),
  set_by TEXT NOT NULL,
  set_at TEXT NOT NULL,
  CHECK (enabled = 0 OR limit_minor IS NOT NULL)
);
CREATE TRIGGER c_approval_rules_append_only BEFORE UPDATE ON c_approval_rules BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
CREATE TRIGGER c_approval_rules_no_delete BEFORE DELETE ON c_approval_rules BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;

-- Reminders that chase people (FOLLOWUP-001). Finance sets the business days
-- after which each open item is chased and the quiet hours; an item's age counts
-- from the first hourly run that saw it open, and each step is sent once.
ALTER TABLE c_business ADD COLUMN reminder_days TEXT NOT NULL DEFAULT '[2,5,10]' CHECK (json_valid(reminder_days));
ALTER TABLE c_business ADD COLUMN quiet_from INTEGER NOT NULL DEFAULT 20 CHECK (quiet_from BETWEEN 0 AND 23);
ALTER TABLE c_business ADD COLUMN quiet_until INTEGER NOT NULL DEFAULT 8 CHECK (quiet_until BETWEEN 0 AND 23);
CREATE TABLE c_reminder_items (
  key TEXT PRIMARY KEY,
  person TEXT NOT NULL,
  claim_id TEXT NOT NULL REFERENCES c_claims(id),
  first_seen_at TEXT NOT NULL
);
CREATE TABLE c_reminders (
  key TEXT NOT NULL REFERENCES c_reminder_items(key),
  step INTEGER NOT NULL,
  person TEXT NOT NULL,
  sent_at TEXT NOT NULL,
  PRIMARY KEY (key, step)
);
CREATE TRIGGER c_reminders_append_only BEFORE UPDATE ON c_reminders BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
CREATE TRIGGER c_reminders_no_delete BEFORE DELETE ON c_reminders BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;

-- Escalation with service levels (FOLLOWUP-002). An approval escalates once it
-- passes the service level, anything else once its reminders are exhausted plus
-- the gap: to the person's approving manager, then finance; NULL gap = off.
ALTER TABLE c_business ADD COLUMN service_level_days INTEGER NOT NULL DEFAULT 3 CHECK (service_level_days BETWEEN 1 AND 30);
ALTER TABLE c_business ADD COLUMN escalation_days INTEGER DEFAULT 2 CHECK (escalation_days IS NULL OR escalation_days BETWEEN 1 AND 30);
CREATE TABLE c_escalations (
  key TEXT NOT NULL REFERENCES c_reminder_items(key),
  level INTEGER NOT NULL CHECK (level IN (1, 2)),
  recipients TEXT NOT NULL CHECK (json_valid(recipients)),
  sent_at TEXT NOT NULL,
  PRIMARY KEY (key, level)
);
CREATE TRIGGER c_escalations_append_only BEFORE UPDATE ON c_escalations BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
CREATE TRIGGER c_escalations_no_delete BEFORE DELETE ON c_escalations BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;

-- Budget alerts name the percentage and period; amounts go in the email only
-- when the owner opts that budget in (REPORT-004, ct 19 Oct 05:16Z).
ALTER TABLE c_budgets ADD COLUMN alert_amounts INTEGER NOT NULL DEFAULT 0 CHECK (alert_amounts IN (0, 1));

-- Automatic reports and scheduled submission (AUTO-001). An expense added without
-- choosing a claim is filed into the employee's open automatic report for its
-- month, or for the spend request (trip) it is linked to; on the owner's schedule
-- each automatic report submits its complete expenses and keeps the rest behind.
ALTER TABLE c_business ADD COLUMN auto_submit TEXT CHECK (auto_submit IS NULL OR auto_submit IN ('daily', 'weekly', 'twice-monthly', 'monthly'));
ALTER TABLE c_claims ADD COLUMN auto_key TEXT;
CREATE INDEX c_claims_auto ON c_claims(employee_email, auto_key);
-- One scheduled submission run per business day it falls on.
CREATE TABLE c_auto_runs (
  day TEXT PRIMARY KEY,
  ran_at TEXT NOT NULL
);

-- Record retention and legal hold (RETAIN-001). The owner sets how many years
-- paid and rejected claims are kept; the hourly run proposes those past it and
-- nothing is removed until the owner confirms. Expiry leaves a receipt, and the
-- exact-expense keys of expired claims stay (as SHA-256) so a receipt is never
-- reimbursed twice. A legal hold on a person, the business or an expense-date
-- period blocks expiry (and ERASURE-001) until the owner releases it.
ALTER TABLE c_business ADD COLUMN retention_years INTEGER NOT NULL DEFAULT 7 CHECK (retention_years BETWEEN 1 AND 30);
CREATE TABLE c_legal_holds (
  id TEXT PRIMARY KEY,
  scope TEXT NOT NULL CHECK (scope IN ('person', 'business', 'period')),
  member_email TEXT,
  from_day TEXT,
  to_day TEXT,
  reason TEXT NOT NULL,
  placed_by TEXT NOT NULL,
  placed_at TEXT NOT NULL,
  released_by TEXT,
  released_at TEXT,
  CHECK ((scope = 'person') = (member_email IS NOT NULL)),
  CHECK ((scope = 'period') = (from_day IS NOT NULL AND to_day IS NOT NULL AND from_day <= to_day))
);
CREATE TABLE c_expiry_proposals (
  id TEXT PRIMARY KEY,
  proposed_at TEXT NOT NULL,
  retention_years INTEGER NOT NULL,
  claims TEXT NOT NULL CHECK (json_valid(claims)),
  status TEXT NOT NULL CHECK (status IN ('proposed', 'confirmed')),
  confirmed_by TEXT,
  confirmed_at TEXT,
  receipt TEXT CHECK (receipt IS NULL OR json_valid(receipt))
);
CREATE TABLE c_expired_keys (
  key_sha256 TEXT PRIMARY KEY CHECK (length(key_sha256) = 64),
  claim_number INTEGER NOT NULL,
  expired_at TEXT NOT NULL
);

-- History stays permanent except inside a confirmed expiry: the expiry batch names
-- the claims and batch it removes here first and clears it last, in one transaction.
CREATE TABLE c_expiring (target TEXT PRIMARY KEY);
DROP TRIGGER c_receipts_no_delete;
CREATE TRIGGER c_receipts_no_delete BEFORE DELETE ON c_receipts WHEN NOT EXISTS(SELECT 1 FROM c_expiring WHERE target=OLD.claim_id)
BEGIN SELECT RAISE(ABORT, 'receipt evidence is permanent'); END;
DROP TRIGGER c_revisions_no_delete;
CREATE TRIGGER c_revisions_no_delete BEFORE DELETE ON c_revisions WHEN NOT EXISTS(SELECT 1 FROM c_expiring WHERE target=OLD.claim_id) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_decisions_no_delete;
CREATE TRIGGER c_decisions_no_delete BEFORE DELETE ON c_decisions WHEN NOT EXISTS(SELECT 1 FROM c_expiring WHERE target=OLD.claim_id) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_comments_no_delete;
CREATE TRIGGER c_comments_no_delete BEFORE DELETE ON c_comments WHEN NOT EXISTS(SELECT 1 FROM c_expiring WHERE target=OLD.claim_id) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_exception_reviews_no_delete;
CREATE TRIGGER c_exception_reviews_no_delete BEFORE DELETE ON c_exception_reviews WHEN NOT EXISTS(SELECT 1 FROM c_expiring WHERE target=OLD.claim_id) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_audit_samples_no_delete;
CREATE TRIGGER c_audit_samples_no_delete BEFORE DELETE ON c_audit_samples WHEN NOT EXISTS(SELECT 1 FROM c_expiring WHERE target=OLD.claim_id) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_events_no_delete;
CREATE TRIGGER c_events_no_delete BEFORE DELETE ON c_events WHEN NOT EXISTS(SELECT 1 FROM c_expiring WHERE target=OLD.claim_id OR target=OLD.batch_id) BEGIN SELECT RAISE(ABORT, 'history is permanent'); END;
DROP TRIGGER c_reminders_no_delete;
CREATE TRIGGER c_reminders_no_delete BEFORE DELETE ON c_reminders WHEN NOT EXISTS(SELECT 1 FROM c_reminder_items r JOIN c_expiring e ON e.target=r.claim_id WHERE r.key=OLD.key) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_escalations_no_delete;
CREATE TRIGGER c_escalations_no_delete BEFORE DELETE ON c_escalations WHEN NOT EXISTS(SELECT 1 FROM c_reminder_items r JOIN c_expiring e ON e.target=r.claim_id WHERE r.key=OLD.key) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;

-- Personal-data erasure (ERASURE-001). History stays permanent except inside an
-- erasure: its batch names the person here first and clears it last, in one
-- transaction, so only that batch may rewrite their address to the opaque
-- "Former member" label, delete their own comments and the reminders sent to them.
-- Receipt bytes, hashes, sizes, names and upload times stay permanent always.
CREATE TABLE c_erasing (email TEXT PRIMARY KEY);
DROP TRIGGER c_receipts_keep_bytes;
CREATE TRIGGER c_receipts_keep_bytes BEFORE UPDATE OF bytes, sha256, size, name, uploaded_at ON c_receipts
BEGIN SELECT RAISE(ABORT, 'receipt evidence is permanent'); END;
CREATE TRIGGER c_receipts_keep_uploader BEFORE UPDATE OF uploaded_by ON c_receipts WHEN NOT EXISTS(SELECT 1 FROM c_erasing)
BEGIN SELECT RAISE(ABORT, 'receipt evidence is permanent'); END;
DROP TRIGGER c_revisions_append_only;
CREATE TRIGGER c_revisions_append_only BEFORE UPDATE ON c_revisions WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_decisions_append_only;
CREATE TRIGGER c_decisions_append_only BEFORE UPDATE ON c_decisions WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_events_append_only;
CREATE TRIGGER c_events_append_only BEFORE UPDATE ON c_events WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'history is permanent'); END;
DROP TRIGGER c_comments_frozen;
CREATE TRIGGER c_comments_frozen BEFORE UPDATE ON c_comments
  WHEN NOT EXISTS(SELECT 1 FROM c_erasing) AND (EXISTS(SELECT 1 FROM c_comments r WHERE r.parent_id=OLD.id) OR NEW.id IS NOT OLD.id OR NEW.claim_id IS NOT OLD.claim_id OR NEW.item_id IS NOT OLD.item_id
    OR NEW.parent_id IS NOT OLD.parent_id OR NEW.author_email IS NOT OLD.author_email OR NEW.on_behalf_of IS NOT OLD.on_behalf_of OR NEW.asks_email IS NOT OLD.asks_email OR NEW.created_at IS NOT OLD.created_at)
  BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_comments_no_delete;
CREATE TRIGGER c_comments_no_delete BEFORE DELETE ON c_comments WHEN NOT EXISTS(SELECT 1 FROM c_expiring WHERE target=OLD.claim_id) AND NOT EXISTS(SELECT 1 FROM c_erasing WHERE email=OLD.author_email)
BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_exception_reviews_append_only;
CREATE TRIGGER c_exception_reviews_append_only BEFORE UPDATE ON c_exception_reviews WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_audit_samples_one_finding;
CREATE TRIGGER c_audit_samples_one_finding BEFORE UPDATE ON c_audit_samples WHEN NOT EXISTS(SELECT 1 FROM c_erasing) AND (OLD.outcome IS NOT NULL OR NEW.claim_id IS NOT OLD.claim_id OR NEW.revision IS NOT OLD.revision OR NEW.ordinal IS NOT OLD.ordinal OR NEW.percent IS NOT OLD.percent OR NEW.sampled_at IS NOT OLD.sampled_at)
  BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_approval_rules_append_only;
CREATE TRIGGER c_approval_rules_append_only BEFORE UPDATE ON c_approval_rules WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_report_deliveries_append_only;
CREATE TRIGGER c_report_deliveries_append_only BEFORE UPDATE ON c_report_deliveries WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_reminders_append_only;
CREATE TRIGGER c_reminders_append_only BEFORE UPDATE ON c_reminders WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_escalations_append_only;
CREATE TRIGGER c_escalations_append_only BEFORE UPDATE ON c_escalations WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_budgets_append_only;
CREATE TRIGGER c_budgets_append_only BEFORE UPDATE ON c_budgets WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_budget_alerts_append_only;
CREATE TRIGGER c_budget_alerts_append_only BEFORE UPDATE ON c_budget_alerts WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_reminders_no_delete;
CREATE TRIGGER c_reminders_no_delete BEFORE DELETE ON c_reminders WHEN NOT EXISTS(SELECT 1 FROM c_reminder_items r JOIN c_expiring e ON e.target=r.claim_id WHERE r.key=OLD.key) AND NOT EXISTS(SELECT 1 FROM c_reminder_items r JOIN c_erasing x ON x.email=r.person WHERE r.key=OLD.key)
BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;
DROP TRIGGER c_escalations_no_delete;
CREATE TRIGGER c_escalations_no_delete BEFORE DELETE ON c_escalations WHEN NOT EXISTS(SELECT 1 FROM c_reminder_items r JOIN c_expiring e ON e.target=r.claim_id WHERE r.key=OLD.key) AND NOT EXISTS(SELECT 1 FROM c_reminder_items r JOIN c_erasing x ON x.email=r.person WHERE r.key=OLD.key)
BEGIN SELECT RAISE(ABORT, 'claim history is permanent'); END;

-- Versioned policy rules (POLICY-001). Finance publishes the whole rule set as a
-- new numbered version with the day it takes effect; versions are never changed
-- or removed, and each policy exception names the version that raised it.
CREATE TABLE c_policies (
  version INTEGER PRIMARY KEY CHECK (version >= 1),
  effective_from TEXT NOT NULL,
  rules TEXT NOT NULL CHECK (json_valid(rules)),
  published_by TEXT NOT NULL,
  published_at TEXT NOT NULL
);
CREATE TRIGGER c_policies_append_only BEFORE UPDATE ON c_policies WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT, 'policy history is permanent'); END;
CREATE TRIGGER c_policies_no_delete BEFORE DELETE ON c_policies BEGIN SELECT RAISE(ABORT, 'policy history is permanent'); END;

-- Owner settings become immutable configuration snapshots of POLICY-001 versions.
CREATE TABLE c_policy_configurations (
  version INTEGER PRIMARY KEY REFERENCES c_policies(version),
  configuration TEXT NOT NULL CHECK(json_valid(configuration))
);
INSERT INTO c_policies(version,effective_from,rules,published_by,published_at)
SELECT 1,substr(updated_at,1,10),'[]','migration',updated_at FROM c_business WHERE id=1 AND NOT EXISTS(SELECT 1 FROM c_policies);
INSERT INTO c_policy_configurations(version,configuration)
SELECT p.version,json_object('legacy_capture',1,'receipt_threshold_minor',b.receipt_threshold_minor,'preapproval_threshold_minor',b.preapproval_threshold_minor,'categories',json(COALESCE((SELECT json_group_array(json_object('id',id,'name',name,'active',active,'limit_minor',limit_minor,'per_person_limit_minor',per_person_limit_minor,'receipt_always',receipt_always,'required_fields',json(required_fields))) FROM c_categories),'[]'))) FROM c_policies p CROSS JOIN c_business b WHERE b.id=1;
CREATE TRIGGER c_policy_configuration_permanent BEFORE UPDATE ON c_policy_configurations BEGIN SELECT RAISE(ABORT, 'policy configuration is permanent'); END;
CREATE TRIGGER c_policy_configuration_no_delete BEFORE DELETE ON c_policy_configurations BEGIN SELECT RAISE(ABORT, 'policy configuration is permanent'); END;

-- Stable opaque member identities; email continues to prove native sign-in.
ALTER TABLE c_members ADD COLUMN member_id TEXT;
UPDATE c_members SET member_id=lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)));
CREATE UNIQUE INDEX c_members_identity ON c_members(member_id);
CREATE TRIGGER c_members_identity AFTER INSERT ON c_members WHEN NEW.member_id IS NULL BEGIN
 UPDATE c_members SET member_id=lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6))) WHERE email=NEW.email;
END;
CREATE TABLE c_import_targets(kind TEXT NOT NULL,id TEXT NOT NULL,revision TEXT NOT NULL,PRIMARY KEY(kind,id));

-- MOVE-003: imported approval configuration uses opaque member identities;
-- each submitted revision keeps its own ordered routing snapshot.
CREATE TABLE c_import_chains (
  id TEXT PRIMARY KEY,
  employee_id TEXT NOT NULL UNIQUE REFERENCES c_members(member_id),
  steps TEXT NOT NULL CHECK (json_valid(steps) AND json_type(steps)='array' AND json_array_length(steps)>0),
  revision TEXT NOT NULL
);
CREATE TABLE c_claim_chains (
  claim_id TEXT NOT NULL,
  revision INTEGER NOT NULL,
  chain_id TEXT NOT NULL,
  steps TEXT NOT NULL CHECK (json_valid(steps) AND json_type(steps)='array' AND json_array_length(steps)>0),
  position INTEGER NOT NULL DEFAULT 0 CHECK (position>=0 AND position<json_array_length(steps)),
  PRIMARY KEY(claim_id,revision),
  FOREIGN KEY(claim_id,revision) REFERENCES c_revisions(claim_id,revision) ON DELETE CASCADE
);
CREATE TRIGGER c_claim_chains_keep_snapshot BEFORE UPDATE OF claim_id,revision,chain_id,steps ON c_claim_chains
  WHEN NOT EXISTS(SELECT 1 FROM c_erasing)
  BEGIN SELECT RAISE(ABORT,'claim routing history is permanent'); END;
CREATE TRIGGER c_claim_chains_no_delete BEFORE DELETE ON c_claim_chains
  WHEN NOT EXISTS(SELECT 1 FROM c_expiring WHERE target=OLD.claim_id)
  BEGIN SELECT RAISE(ABORT,'claim routing history is permanent'); END;

-- One decision per ordered step, retaining the existing default for claims
-- with one approver and every decision already on record.
CREATE TABLE c_decisions_next (
  id TEXT PRIMARY KEY,
  claim_id TEXT NOT NULL,
  revision INTEGER NOT NULL,
  decision TEXT NOT NULL CHECK (decision IN ('approved','returned','rejected')),
  reason TEXT NOT NULL,
  actor_email TEXT NOT NULL,
  at TEXT NOT NULL,
  exceptions TEXT NOT NULL CHECK (json_valid(exceptions)),
  on_behalf_of TEXT,
  decision_step INTEGER NOT NULL DEFAULT 0 CHECK (decision_step>=0),
  FOREIGN KEY(claim_id,revision) REFERENCES c_revisions(claim_id,revision),
  UNIQUE(claim_id,revision,decision_step)
);
INSERT INTO c_decisions_next(id,claim_id,revision,decision,reason,actor_email,at,exceptions,on_behalf_of)
  SELECT id,claim_id,revision,decision,reason,actor_email,at,exceptions,on_behalf_of FROM c_decisions;
DROP TRIGGER c_decisions_append_only;
DROP TRIGGER c_decisions_no_delete;
DROP TABLE c_decisions;
ALTER TABLE c_decisions_next RENAME TO c_decisions;
CREATE TRIGGER c_decisions_append_only BEFORE UPDATE ON c_decisions
  WHEN NOT EXISTS(SELECT 1 FROM c_erasing)
  BEGIN SELECT RAISE(ABORT,'claim history is permanent'); END;
CREATE TRIGGER c_decisions_no_delete BEFORE DELETE ON c_decisions
  WHEN NOT EXISTS(SELECT 1 FROM c_expiring WHERE target=OLD.claim_id)
  BEGIN SELECT RAISE(ABORT,'claim history is permanent'); END;

-- REPORT-005: expenses explicitly marked for customer rebilling.
ALTER TABLE c_items ADD COLUMN billable INTEGER NOT NULL DEFAULT 0 CHECK (billable IN (0,1));
ALTER TABLE c_items ADD COLUMN customer TEXT NOT NULL DEFAULT '';

-- PAY-004: who may release payments, dual release above an amount, the release record and the reimbursement day.
ALTER TABLE c_members ADD COLUMN may_release INTEGER NOT NULL DEFAULT 0 CHECK (may_release IN (0, 1));
ALTER TABLE c_business ADD COLUMN dual_release_over_minor INTEGER CHECK (dual_release_over_minor IS NULL OR dual_release_over_minor >= 0);
ALTER TABLE c_business ADD COLUMN pay_weekday INTEGER CHECK (pay_weekday IS NULL OR pay_weekday BETWEEN 0 AND 6);
ALTER TABLE c_batches ADD COLUMN first_released_by TEXT;
ALTER TABLE c_batches ADD COLUMN first_released_at TEXT;
ALTER TABLE c_batches ADD COLUMN released_by TEXT;
ALTER TABLE c_batches ADD COLUMN released_at TEXT;
-- One row per business-time-zone day the reimbursement schedule ran, so the hourly run opens at most one batch a day.
CREATE TABLE c_pay_runs (
  day TEXT PRIMARY KEY,
  ran_at TEXT NOT NULL,
  batch_id TEXT
);

-- CLAIM-008: contractors claim as non-employees, and finance marks expenses it treats as non-accountable (taxable).
ALTER TABLE c_members ADD COLUMN is_contractor INTEGER NOT NULL DEFAULT 0 CHECK (is_contractor IN (0, 1));
CREATE TABLE c_nonaccountable (
  item_id TEXT PRIMARY KEY,
  claim_id TEXT NOT NULL,
  marked_by TEXT NOT NULL,
  marked_at TEXT NOT NULL,
  reason TEXT NOT NULL
);
CREATE INDEX c_nonaccountable_claim ON c_nonaccountable(claim_id);

ALTER TABLE c_business ADD COLUMN fx_enabled INTEGER NOT NULL DEFAULT 0 CHECK(fx_enabled IN (0,1));
ALTER TABLE c_items ADD COLUMN original_minor INTEGER;
ALTER TABLE c_items ADD COLUMN original_currency TEXT NOT NULL DEFAULT '';
ALTER TABLE c_items ADD COLUMN fx_rate TEXT NOT NULL DEFAULT '';
ALTER TABLE c_items ADD COLUMN fx_date TEXT NOT NULL DEFAULT '';
ALTER TABLE c_items ADD COLUMN fx_source TEXT NOT NULL DEFAULT '';
ALTER TABLE c_items ADD COLUMN original_sales_tax_minor INTEGER;
ALTER TABLE c_allocations ADD COLUMN original_minor INTEGER;

-- APPROVE-001: versioned owner configuration and frozen per-revision tasks.
CREATE TABLE c_approval_workflows (
 version INTEGER PRIMARY KEY,
 rules TEXT NOT NULL CHECK(json_valid(rules)),
 created_by TEXT NOT NULL,
 created_at TEXT NOT NULL
);
CREATE TRIGGER c_approval_workflows_immutable BEFORE UPDATE ON c_approval_workflows WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT,'workflow versions are permanent'); END;
CREATE TABLE c_workflow_tasks (
 kind TEXT NOT NULL CHECK(kind IN ('claim','request')),
 record_id TEXT NOT NULL,
 revision INTEGER NOT NULL,
 slot INTEGER NOT NULL,
 stage INTEGER NOT NULL,
 email TEXT NOT NULL,
 on_behalf_of TEXT,
 role TEXT NOT NULL CHECK(role IN ('manager','finance')),
 status TEXT NOT NULL DEFAULT 'waiting' CHECK(status IN ('waiting','approved')),
 PRIMARY KEY(kind,record_id,revision,slot)
);
ALTER TABLE c_decisions ADD COLUMN workflow_final INTEGER NOT NULL DEFAULT 1 CHECK(workflow_final IN (0,1));
ALTER TABLE c_requests ADD COLUMN workflow TEXT CHECK(workflow IS NULL OR json_valid(workflow));
CREATE TRIGGER c_approval_workflows_no_delete BEFORE DELETE ON c_approval_workflows BEGIN SELECT RAISE(ABORT,'workflow versions are permanent'); END;

-- Durable opaque source reservations survive import undo and financial retention.
-- No personal fields or imported bytes are duplicated here.
CREATE TABLE c_cutover_items (
  source_key TEXT PRIMARY KEY CHECK (length(source_key) = 64),
  claim_id TEXT NOT NULL,
  item_id TEXT NOT NULL UNIQUE
);
CREATE TABLE c_cutover_reports (
  source_key TEXT PRIMARY KEY CHECK (length(source_key) = 64),
  claim_id TEXT NOT NULL UNIQUE
);
CREATE TRIGGER c_cutover_items_no_update BEFORE UPDATE ON c_cutover_items BEGIN SELECT RAISE(ABORT, 'cutover reservation is permanent'); END;
CREATE TRIGGER c_cutover_items_no_delete BEFORE DELETE ON c_cutover_items BEGIN SELECT RAISE(ABORT, 'cutover reservation is permanent'); END;
CREATE TRIGGER c_cutover_reports_no_update BEFORE UPDATE ON c_cutover_reports BEGIN SELECT RAISE(ABORT, 'cutover reservation is permanent'); END;
CREATE TRIGGER c_cutover_reports_no_delete BEFORE DELETE ON c_cutover_reports BEGIN SELECT RAISE(ABORT, 'cutover reservation is permanent'); END;

-- CAPTURE-004: finance-confirmed, off-by-default draft preparation; no duplicate R2 object or inferred amount.
CREATE TABLE c_capture_window (
