-- without confusing ciphertext tampering or a wrong current secret with restore.
ALTER TABLE rer_dependency_installation ADD COLUMN key_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(key_ids) AND json_type(key_ids)='array');

-- Web Connector credentials and live tickets never travel in an archive.
CREATE TABLE c_qbd_connection (
 id INTEGER PRIMARY KEY CHECK(id=1), username TEXT NOT NULL, password_hash TEXT NOT NULL,
 company TEXT NOT NULL, file_id TEXT NOT NULL, owner_id TEXT NOT NULL,
 connected_by TEXT NOT NULL, connected_at TEXT NOT NULL
);
CREATE TABLE c_qbd_tickets (
 ticket_hash TEXT PRIMARY KEY, expires INTEGER NOT NULL, request_id TEXT,
 last_request TEXT, last_result INTEGER, error TEXT NOT NULL DEFAULT ''
);
CREATE TABLE c_qbd_catalog (
 kind TEXT NOT NULL, list_id TEXT NOT NULL, name TEXT NOT NULL, active INTEGER NOT NULL,
 PRIMARY KEY(kind,list_id)
);
CREATE TABLE c_qbd_mappings (name TEXT PRIMARY KEY, kind TEXT NOT NULL, list_id TEXT NOT NULL);
CREATE TABLE c_qbd_requests (
 id TEXT PRIMARY KEY, source TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, payload TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN('pending','sent','succeeded','failed','uncertain')),
 message TEXT NOT NULL DEFAULT '', txn_id TEXT, attempts INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL, completed_at TEXT
);
CREATE TRIGGER c_qbd_source_fixed BEFORE UPDATE OF source,kind ON c_qbd_requests WHEN NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT,'posting identity is permanent'); END;
CREATE TRIGGER c_qbd_success_fixed BEFORE UPDATE ON c_qbd_requests WHEN OLD.status='succeeded' AND NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT,'successful posting is permanent'); END;
CREATE TRIGGER c_qbd_success_kept BEFORE DELETE ON c_qbd_requests WHEN OLD.status='succeeded' AND NOT EXISTS(SELECT 1 FROM c_erasing) BEGIN SELECT RAISE(ABORT,'successful posting is permanent'); END;

-- Installation mail intake and private original-message custody.
CREATE TABLE c_receipt_mail_settings (
 id INTEGER PRIMARY KEY CHECK(id=1), address TEXT NOT NULL, version INTEGER NOT NULL,
 consent_at TEXT NOT NULL, set_by TEXT NOT NULL
);
CREATE TABLE c_receipt_mail_aliases (
 email TEXT PRIMARY KEY, owner_email TEXT NOT NULL, proof_hash TEXT NOT NULL,
 expires_at TEXT NOT NULL, confirmed_at TEXT, requested_at TEXT NOT NULL
);
CREATE TABLE c_receipt_mail_messages (
 id TEXT PRIMARY KEY, sha256 TEXT NOT NULL UNIQUE, object_key TEXT NOT NULL UNIQUE,
 size INTEGER NOT NULL CHECK(size>0 AND size<=25000000), sender TEXT NOT NULL,
 recipient TEXT NOT NULL, subject TEXT NOT NULL, owner_email TEXT,
 received_at TEXT NOT NULL, held_reason TEXT NOT NULL,
 CHECK ((owner_email IS NULL AND held_reason<>'') OR (owner_email IS NOT NULL AND held_reason=''))
);
CREATE TABLE c_receipt_mail_sources (
 receipt_id TEXT PRIMARY KEY REFERENCES c_capture_receipts(id),
 message_id TEXT NOT NULL REFERENCES c_receipt_mail_messages(id)
);
CREATE TRIGGER c_receipt_mail_messages_permanent BEFORE UPDATE OF id,sha256,object_key,size,recipient,subject,received_at,held_reason ON c_receipt_mail_messages
BEGIN SELECT RAISE(ABORT,'source mail is permanent'); END;
CREATE TRIGGER c_receipt_mail_messages_no_delete BEFORE DELETE ON c_receipt_mail_messages
BEGIN SELECT RAISE(ABORT,'source mail is permanent'); END;
CREATE TRIGGER c_receipt_mail_sources_permanent BEFORE UPDATE ON c_receipt_mail_sources
BEGIN SELECT RAISE(ABORT,'source mail is permanent'); END;
CREATE TRIGGER c_receipt_mail_sources_no_delete BEFORE DELETE ON c_receipt_mail_sources
BEGIN SELECT RAISE(ABORT,'source mail is permanent'); END;
CREATE TRIGGER c_receipt_mail_messages_identity BEFORE UPDATE OF sender,owner_email ON c_receipt_mail_messages WHEN NOT EXISTS(SELECT 1 FROM c_capture_erasing)
BEGIN SELECT RAISE(ABORT,'source mail identity is permanent'); END;
-- One complete reference inventory for both original-message and receipt objects.
CREATE TABLE c_capture_objects (object_key TEXT PRIMARY KEY);
INSERT INTO c_capture_objects(object_key) SELECT object_key FROM c_capture_receipts;
CREATE TRIGGER c_capture_objects_from_receipt AFTER INSERT ON c_capture_receipts
BEGIN INSERT OR IGNORE INTO c_capture_objects(object_key) VALUES(NEW.object_key); END;
CREATE TRIGGER c_capture_objects_from_mail AFTER INSERT ON c_receipt_mail_messages
BEGIN INSERT OR IGNORE INTO c_capture_objects(object_key) VALUES(NEW.object_key); END;
CREATE TRIGGER c_capture_objects_permanent BEFORE UPDATE ON c_capture_objects
BEGIN SELECT RAISE(ABORT,'original object references are permanent'); END;
CREATE TRIGGER c_capture_objects_no_delete BEFORE DELETE ON c_capture_objects
BEGIN SELECT RAISE(ABORT,'original object references are permanent'); END;

-- Private reply credentials travel with installation archives, never claim history.
CREATE TABLE c_comment_email_tokens (
 question_id TEXT PRIMARY KEY REFERENCES c_comments(id) ON DELETE CASCADE,
 token_hash TEXT NOT NULL UNIQUE,
 member_id TEXT NOT NULL,
 destination TEXT NOT NULL,
 created_at TEXT NOT NULL
);
CREATE TABLE c_comment_email_answers (
 message_sha256 TEXT PRIMARY KEY CHECK(length(message_sha256)=64),
 comment_id TEXT NOT NULL UNIQUE REFERENCES c_comments(id) ON DELETE CASCADE
);
CREATE TRIGGER c_comment_email_tokens_permanent BEFORE UPDATE ON c_comment_email_tokens
BEGIN SELECT RAISE(ABORT,'question reply credential is permanent'); END;
CREATE TRIGGER c_comment_email_answers_permanent BEFORE UPDATE ON c_comment_email_answers
BEGIN SELECT RAISE(ABORT,'email answer provenance is permanent'); END;
-- Erasure invalidates outstanding credentials in the same transaction, including
-- questions authored by someone else and addressed to the erased member.
CREATE TRIGGER c_comment_email_erasure AFTER INSERT ON c_erasing
BEGIN
 DELETE FROM c_comment_email_tokens WHERE member_id IN (SELECT member_id FROM c_members WHERE email=NEW.email)
  OR question_id IN (SELECT id FROM c_comments WHERE author_email=NEW.email OR asks_email=NEW.email);
END;

-- Historical sources retain unknown origin; only newly parsed messages identify their parts.
ALTER TABLE c_receipt_mail_sources ADD COLUMN origin TEXT CHECK(origin IN ('body','attachment'));
CREATE INDEX c_receipt_mail_sources_message ON c_receipt_mail_sources(message_id);

CREATE TABLE c_plaid_settings (
  id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL,
  credentials_sealed TEXT NOT NULL, account_monthly_minor INTEGER NOT NULL CHECK(account_monthly_minor>=0),
  monthly_cap_minor INTEGER CHECK(monthly_cap_minor>=0), set_by TEXT NOT NULL, set_at TEXT NOT NULL
);
CREATE TABLE c_plaid_links (
  id TEXT PRIMARY KEY, member_email TEXT NOT NULL, session_id TEXT NOT NULL,
  scope TEXT NOT NULL CHECK(scope IN ('company','personal')), settings_version INTEGER NOT NULL,
  expires_at INTEGER NOT NULL, delegate_grant TEXT, public_token_hash TEXT UNIQUE, reserved_at TEXT
);
CREATE TABLE c_plaid_connections (
  id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN ('company','personal')),
  personal_email TEXT, item_id TEXT NOT NULL UNIQUE, credentials_sealed TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('pending','connected')),
  accounts TEXT NOT NULL CHECK(json_valid(accounts)), connected_by TEXT NOT NULL, connected_at TEXT NOT NULL,
  CHECK((scope='company' AND personal_email IS NULL) OR (scope='personal' AND personal_email IS NOT NULL))
);
CREATE TABLE c_plaid_costs (
  month TEXT NOT NULL, connection_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('reserved','settled')), accounts INTEGER NOT NULL CHECK(accounts>0),
  account_monthly_minor INTEGER NOT NULL CHECK(account_monthly_minor>=0), usd_minor INTEGER NOT NULL CHECK(usd_minor>=0),
  recorded_at TEXT NOT NULL, PRIMARY KEY(month,connection_id,kind)
);

-- FEED-006: liability is immutable import provenance; personal classification freezes with each revision.
ALTER TABLE c_program_feeds ADD COLUMN liability TEXT NOT NULL DEFAULT 'company' CHECK(liability IN ('company','individual'));
ALTER TABLE c_card_charges ADD COLUMN liability TEXT NOT NULL DEFAULT 'company' CHECK(liability IN ('company','individual'));
ALTER TABLE c_card_charges ADD COLUMN program_id TEXT;
ALTER TABLE c_card_charge_undo_history ADD COLUMN liability TEXT NOT NULL DEFAULT 'company' CHECK(liability IN ('company','individual'));
ALTER TABLE c_card_charge_undo_history ADD COLUMN program_id TEXT;
ALTER TABLE c_items ADD COLUMN card_liability TEXT NOT NULL DEFAULT 'company' CHECK(card_liability IN ('company','individual'));
ALTER TABLE c_items ADD COLUMN card_personal INTEGER NOT NULL DEFAULT 0 CHECK(card_personal IN (0,1));
CREATE TRIGGER c_program_liability_keep BEFORE UPDATE OF liability ON c_program_feeds
 WHEN NEW.liability IS NOT OLD.liability BEGIN SELECT RAISE(ABORT,'program liability is immutable'); END;
CREATE TRIGGER c_charge_liability_keep BEFORE UPDATE OF liability,program_id ON c_card_charges
 WHEN NEW.liability IS NOT OLD.liability OR NEW.program_id IS NOT OLD.program_id BEGIN SELECT RAISE(ABORT,'charge liability is immutable'); END;
CREATE TRIGGER c_individual_charge_owner_keep BEFORE UPDATE OF employee_email,claim_id ON c_card_charges
 WHEN OLD.liability='individual' AND NOT EXISTS(SELECT 1 FROM c_erasing)
 AND (NEW.employee_email IS NOT OLD.employee_email OR NEW.claim_id IS NOT OLD.claim_id)
 BEGIN SELECT RAISE(ABORT,'individual liability remains with its original cardholder'); END;
CREATE TRIGGER c_item_liability_insert BEFORE INSERT ON c_items WHEN
 (NEW.card_charge_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM c_card_charges ch WHERE ch.id=NEW.card_charge_id AND ch.liability=NEW.card_liability))
 OR (NEW.card_personal=1 AND (NEW.card_charge_id IS NULL OR NEW.card_liability<>'individual'))
 BEGIN SELECT RAISE(ABORT,'card liability must match its immutable charge'); END;
CREATE TRIGGER c_item_liability_update BEFORE UPDATE OF card_liability,card_personal ON c_items WHEN
 NEW.card_liability IS NOT OLD.card_liability OR
 (NEW.card_personal IS NOT OLD.card_personal AND (OLD.card_liability<>'individual' OR OLD.card_charge_id IS NULL OR NOT EXISTS(SELECT 1 FROM c_claims c WHERE c.id=OLD.claim_id AND c.status IN ('draft','returned'))))
 BEGIN SELECT RAISE(ABORT,'submitted card classification is frozen'); END;
DROP TRIGGER c_card_charge_undo_capture;
CREATE TRIGGER c_card_charge_undo_capture BEFORE DELETE ON c_card_charges
 BEGIN INSERT INTO c_card_charge_undo_history(id,file_id,card_id,employee_email,transaction_key,posted_on,transaction_on,descriptor,memo,amount_minor,currency,original_minor,original_currency,item_id,category_id,created_at,claim_id,liability,program_id) VALUES(OLD.id,OLD.file_id,OLD.card_id,OLD.employee_email,OLD.transaction_key,OLD.posted_on,OLD.transaction_on,OLD.descriptor,OLD.memo,OLD.amount_minor,OLD.currency,OLD.original_minor,OLD.original_currency,OLD.item_id,OLD.category_id,OLD.created_at,OLD.claim_id,OLD.liability,OLD.program_id); END;

